import unittest
from candidate import largest_prime_factor

class TestLargestPrimeFactor(unittest.TestCase):
    def test_largest_prime_factor_normal_case_13195_returns_29(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_largest_prime_factor_normal_case_2048_returns_2(self):
        self.assertEqual(largest_prime_factor(2048), 2)

    def test_largest_prime_factor_boundary_smallest_prime(self):
        self.assertEqual(largest_prime_factor(2), 2)

    def test_largest_prime_factor_prime_number_three(self):
        self.assertEqual(largest_prime_factor(3), 3)

    def test_largest_prime_factor_composite_four(self):
        self.assertEqual(largest_prime_factor(4), 2)

    def test_largest_prime_factor_composite_six(self):
        self.assertEqual(largest_prime_factor(6), 3)

    def test_largest_prime_factor_edge_case_one(self):
        self.assertEqual(largest_prime_factor(1), 1)

    def test_largest_prime_factor_edge_case_zero(self):
        self.assertEqual(largest_prime_factor(0), 1)

    def test_largest_prime_factor_edge_case_negative(self):
        self.assertEqual(largest_prime_factor(-5), 1)

    def test_largest_prime_factor_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(None)

    def test_largest_prime_factor_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            largest_prime_factor("13195")
